UPDATE draw_order SET award_fulfillment_status = #{awardFulfillmentStatus}, fulfilled_at = NOW(3),
    fulfillment_event_status = 1, fulfillment_retry_at = NULL, update_time = NOW()
WHERE u_id = #{uId} AND order_id = #{orderId} AND award_id = #{awardId}
  AND stock_settlement_event_status = 1
  AND COALESCE(award_fulfillment_status,0) != #{awardFulfillmentStatus}


UPDATE draw_order SET fulfillment_event_status = 1, update_time = NOW(), fulfillment_retry_at = NULL
WHERE u_id = #{uId} AND order_id = #{orderId}
  AND #{fulfillmentEventStatus}=1 AND award_fulfillment_status=1 AND fulfillment_event_status=0


UPDATE draw_order SET stock_settlement_event_status = 4, stock_retry_at = NULL, update_time = NOW()
WHERE u_id = #{uId} AND order_id = #{orderId}
  AND stock_settlement_event_status=0
